class Node {
  public Integer value;
  public Node left;
  public Node right;

  public Node(Integer value) {
    this.value = value;
    this.left = null;
    this.right = null;
  }
}

class ContainsTarget {
  public boolean solve(Node root, int target) {
    Node curNode = root;
    while (curNode != null) {
      if (curNode.value == target) {
        return true;
      } else if (curNode.value > target) {
        curNode = curNode.left;
      } else {
        curNode = curNode.right;
      }
    }
    return false;
  }
}

